<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue';
import {api} from '../api';
import {COPY} from '../copy';
import type {BrowseResult} from '../types';
import StatusChip from '../components/StatusChip.vue';
const props=defineProps<{initial?:BrowseResult}>();defineEmits<{open:[id:number]}>();
const group=ref('zk_high'),level=ref('all'),letter=ref('all'),status=ref('all'),result=ref<BrowseResult>(props.initial??{items:[],total:0,page:1,size:50,group:'zk_high',coverage:{ranked:0,total:0}}),busy=ref(false),failed=ref(false);let request=0,alive=true;
const letters=['all',...'abcdefghijklmnopqrstuvwxyz'];
async function load(more=false){const n=++request;busy.value=true;failed.value=false;const page=more?result.value.page+1:1;try{const r=await api<BrowseResult>(`/api/browse?group=${group.value}&level=${level.value}&letter=${letter.value}&status=${status.value}&page=${page}&size=50`);if(alive&&n===request)result.value={...r,items:more?[...result.value.items,...r.items]:r.items};}catch{if(alive&&n===request)failed.value=true;}finally{if(alive&&n===request)busy.value=false;}}
watch([group,level,letter,status],()=>{result.value={...result.value,items:[]};load();});onMounted(()=>{if(!props.initial)load();});onUnmounted(()=>{alive=false;request++;});
</script>
<template><main class="page browse-page"><h1>{{ COPY.wordList }}</h1><div class="seg lg"><button v-for="(label,key) in {zk_high:COPY.zkHigh,daily_high:COPY.dailyHigh}" :key="key" type="button" :class="{on:group===key}" @click="group=key">{{ label }}</button></div><div v-if="group==='zk_high'" class="note infer-note"><b>「{{ COPY.inferred }}」</b><span>{{ COPY.zkHighNote }}</span></div><p v-else class="note">{{ COPY.dailyHighNote }}</p><p v-if="result.coverage.ranked===0" class="note">{{ COPY.unrankedNote }}</p><div class="filters"><div><span class="lbl">{{ COPY.levelLabel }}</span><div class="pills"><button v-for="(label,key) in {all:COPY.all,core:COPY.core,level2:COPY.level2}" :key="key" type="button" :class="{on:level===key}" @click="level=key">{{ label }}</button></div></div><div><span class="lbl">{{ COPY.learningStatus }}</span><div class="pills"><button v-for="(label,key) in {all:COPY.all,...COPY.statuses}" :key="key" type="button" :class="{on:status===key}" @click="status=key">{{ label }}</button></div></div></div><div class="letters" :aria-label="COPY.letterLabel"><button v-for="l in letters" :key="l" type="button" :class="{on:letter===l}" @click="letter=l">{{ l==='all'?COPY.all:l.toUpperCase() }}</button></div><div class="listhead"><span>{{ COPY.browseHead(result.total,letter,group) }}</span><span v-if="result.items.length">1–{{ result.items.length }}</span></div><div class="blist"><button v-for="(w,i) in result.items" :key="w.id" class="brow" type="button" @click="$emit('open',w.id)"><div class="rk">{{ w.rank===null?'·':i+1 }}<span v-if="w.isInferred" class="infer">{{ COPY.inferred }}</span></div><div class="w">{{ w.headword }}<small>{{ w.phonetic }}</small></div><div class="m">{{ w.firstMeaning }}<div v-if="w.basis" class="basis">{{ COPY.basis }}{{ w.basis }}</div></div><div class="tags"><span class="tag" :class="{core:w.level==='三级'}">{{ w.level==='三级'?COPY.core:COPY.level2 }}</span><StatusChip :status="w.status" /></div></button></div><button v-if="result.items.length<result.total" type="button" class="btn more" :disabled="busy" @click="load(true)">{{ COPY.loadMore }}</button><button v-if="failed" type="button" class="btn more" @click="load()">{{ COPY.retry }}</button></main></template>
